from ldm.models.diffusion.ddpm import LatentDiffusion
from ldm.util import default, log_txt_as_img, exists, ismap, isimage, mean_flat, count_params, instantiate_from_config
from torchvision.utils import make_grid
from einops import rearrange, repeat
import torch
from torch import nn, einsum
import numpy as np

class CustomDiffusion(LatentDiffusion):
    def __init__(self,
                 freeze_model='crossattn-kv',
                 cond_stage_trainable=False,
                 add_token=False,
                 *args, **kwargs):

        self.freeze_model = freeze_model
        self.add_token = add_token
        self.cond_stage_trainable = cond_stage_trainable
        super().__init__(cond_stage_trainable=cond_stage_trainable, *args, **kwargs)

        # Selectively freeze parameters in the diffusion model to avoid redundant encoder recomputation.
        if self.freeze_model == 'crossattn-kv':
            for name, param in self.model.diffusion_model.named_parameters():
                if 'transformer_blocks' not in name:
                    param.requires_grad = False
                elif not ('attn2.to_k' in name or 'attn2.to_v' in name):
                    param.requires_grad = False
                else:
                    param.requires_grad = True
        elif self.freeze_model == 'crossattn':
            for name, param in self.model.diffusion_model.named_parameters():
                if 'transformer_blocks' not in name:
                    param.requires_grad = False
                elif 'attn2' not in name:
                    param.requires_grad = False
                else:
                    param.requires_grad = True

        # Disable checkpointing inside transformer blocks
        def change_checkpoint(model):
            for layer in model.children():
                if type(layer).__name__ == 'BasicTransformerBlock':
                    layer.checkpoint = False
                else:
                    change_checkpoint(layer)
        change_checkpoint(self.model.diffusion_model)

        # Modify the forward pass of the CrossAttention blocks to enable parallel processing in the decoder.
        def new_forward(self, x, context=None, mask=None):
            h = self.heads
            crossattn = False
            if context is not None:
                crossattn = True
            q = self.to_q(x)
            context = default(context, x)
            k = self.to_k(context)
            v = self.to_v(context)

            # For cross-attention, detach non-key time steps to reuse cached encoder features
            if crossattn:
                modifier = torch.ones_like(k)
                modifier[:, :1, :] = 0.0  # zero-out for non-key positions
                k = modifier * k + (1 - modifier) * k.detach()
                v = modifier * v + (1 - modifier) * v.detach()

            # Rearrange for multihead attention
            q, k, v = map(lambda t: rearrange(t, 'b n (h d) -> (b h) n d', h=h), (q, k, v))
            sim = einsum('b i d, b j d -> b i j', q, k) * self.scale
            attn = sim.softmax(dim=-1)
            out = einsum('b i j, b j d -> b i d', attn, v)
            out = rearrange(out, '(b h) n d -> b n (h d)', h=h)
            return self.to_out(out)

        def change_forward(model):
            for layer in model.children():
                if type(layer).__name__ == 'CrossAttention':
                    bound_method = new_forward.__get__(layer, layer.__class__)
                    setattr(layer, 'forward', bound_method)
                else:
                    change_forward(layer)
        change_forward(self.model.diffusion_model)

    def configure_optimizers(self):
        lr = self.learning_rate
        params = []
        if self.freeze_model == 'crossattn-kv':
            for name, param in self.model.diffusion_model.named_parameters():
                if 'transformer_blocks' in name and ('attn2.to_k' in name or 'attn2.to_v' in name):
                    params.append(param)
                    print('Optimizing:', name)
        elif self.freeze_model == 'crossattn':
            for name, param in self.model.diffusion_model.named_parameters():
                if 'transformer_blocks' in name and ('attn2' in name):
                    params.append(param)
                    print('Optimizing:', name)
        else:
            params = list(self.model.parameters())

        if self.cond_stage_trainable:
            print(f"Also optimizing conditioning stage parameters!")
            if self.add_token:
                params += list(self.cond_stage_model.transformer.text_model.embeddings.token_embedding.parameters())
            else:
                params += list(self.cond_stage_model.parameters())

        if self.learn_logvar:
            print('Optimizing logvar')
            params.append(self.logvar)
        opt = torch.optim.AdamW(params, lr=lr)
        return opt

    def p_losses(self, x_start, cond, t, mask=None, noise=None):
        # Prior noise injection strategy: inject a sampled noise to x_start at time t
        noise = default(noise, lambda: torch.randn_like(x_start))
        x_noisy = self.q_sample(x_start=x_start, t=t, noise=noise)
        model_output = self.apply_model(x_noisy, t, cond)

        if self.parameterization == "x0":
            target = x_start
        elif self.parameterization == "eps":
            target = noise
        else:
            raise NotImplementedError()

        loss_simple = self.get_loss(model_output, target, mean=False)
        if mask is not None:
            loss_simple = (loss_simple * mask).sum([1,2,3]) / mask.sum([1,2,3])
        else:
            loss_simple = loss_simple.mean([1,2,3])

        logvar_t = (self.logvar.to(self.device))[t]
        loss = loss_simple / torch.exp(logvar_t) + logvar_t
        loss = self.l_simple_weight * loss.mean()
        return loss

    def get_input_withmask(self, batch, **args):
        out = super().get_input(batch, self.first_stage_key, **args)
        mask = batch["mask"]
        if len(mask.shape) == 3:
            mask = mask[..., None]
        mask = rearrange(mask, 'b h w c -> b c h w')
        mask = mask.to(memory_format=torch.contiguous_format).float()
        out += [mask]
        return out

    def training_step(self, batch, batch_idx):
        # Training step applies the diffusion loss with prior noise injection and uses the mask if provided
        if isinstance(batch, list):
            train_batch = batch[0]
            train2_batch = batch[1]
            loss_train = self.shared_step(train_batch)
            loss_train2 = self.shared_step(train2_batch)
            loss = loss_train + loss_train2
        else:
            loss = self.shared_step(batch)
        self.log_dict({"loss": loss.item()}, prog_bar=True, on_step=True, on_epoch=True)
        return loss

    def shared_step(self, batch, **kwargs):
        x, c, mask = self.get_input_withmask(batch, **kwargs)
        loss = self(x, c, mask=mask)
        return loss

### Minimal JAX Core Implementation

# This code implements a stripped‐down version of the core JAX method, including
# the definitions of primitives, a bind mechanism for dispatching to interpretation
# rules, a simple evaluation interpreter, and a forward–mode (JVP) automatic
# differentiation interpreter using dual numbers.

from typing import NamedTuple, Any
import numpy as np
import jax.numpy as jnp

# ---------------------------------------------------------------------------
# Define Primitives: basic operations that form the computational building blocks.

class Primitive(NamedTuple):
    name: str

# Define a few sample primitive operations.
add_p = Primitive('add')
mul_p = Primitive('mul')
sin_p = Primitive('sin')
cos_p = Primitive('cos')
neg_p = Primitive('neg')

# ---------------------------------------------------------------------------
# Bind mechanism: dispatch a primitive application to its implementation

def bind(prim: Primitive, *args, **params):
    # In a full implementation, this function would check for active tracers
    # (e.g. for autodiff, JIT, etc.) and dispatch accordingly. Here we simply
    # call the implementation rule from a dictionary.
    return impl_rules[prim](*args, **params)

# User‐facing functions that wrap primitives:

def add(x, y):
    return bind(add_p, x, y)

def mul(x, y):
    return bind(mul_p, x, y)


def sin(x):
    return bind(sin_p, x)

def cos(x):
    return bind(cos_p, x)


def neg(x):
    return bind(neg_p, x)

# ---------------------------------------------------------------------------
# Evaluation Interpreter: Standard (eager) evaluation

# In the simplest case, values are just concrete numbers and no tracing is done.
# The evaluation rules simply call the corresponding numpy or jax.numpy functions.

impl_rules = {}
impl_rules[add_p] = lambda x, y: np.add(x, y)
impl_rules[mul_p] = lambda x, y: np.multiply(x, y)
impl_rules[sin_p] = lambda x: np.sin(x)
impl_rules[cos_p] = lambda x: np.cos(x)
impl_rules[neg_p] = lambda x: np.negative(x)

# A simple example function written using the primitives.

def foo(x):
    # Computes x * (x + 3)
    return mul(x, add(x, 3.0))

# ---------------------------------------------------------------------------
# Forward–Mode Automatic Differentiation (JVP) Interpreter

from dataclasses import dataclass

@dataclass
class DualNumber:
    primal: float
    tangent: float

# The JVP interpreter propagates dual numbers (primal, tangent pairs).
# It interprets each operation on DualNumbers according to the Jacobian–vector
# product rules.

class JVPInterpreter:
    def __init__(self, prev_interpreter: Any):
        # Typically, we would store the previous (base) interpreter context;
        # here we simply assume evaluation for constant parts.
        self.prev = prev_interpreter

    def lift(self, x):
        # Lift a scalar constant to a dual number with zero tangent.
        if isinstance(x, DualNumber):
            return x
        else:
            return DualNumber(x, 0.0)

    def interpret_op(self, op: Primitive, args):
        # First, lift all arguments to dual numbers.
        args = tuple(self.lift(a) for a in args)
        if op == add_p:
            x, y = args
            return DualNumber(x.primal + y.primal, x.tangent + y.tangent)
        elif op == mul_p:
            x, y = args
            return DualNumber(x.primal * y.primal,
                              x.primal * y.tangent + x.tangent * y.primal)
        elif op == sin_p:
            (x,) = args
            return DualNumber(np.sin(x.primal), np.cos(x.primal) * x.tangent)
        elif op == cos_p:
            (x,) = args
            return DualNumber(np.cos(x.primal), -np.sin(x.primal) * x.tangent)
        elif op == neg_p:
            (x,) = args
            return DualNumber(-x.primal, -x.tangent)
        else:
            raise ValueError(f"Unknown primitive: {op}")

# A simple wrapper for running forward-mode AD using the JVP interpreter.

def jvp(f, x, x_dot):
    # Create a dual input from the primal value and its tangent (perturbation).
    jvp_interp = JVPInterpreter(prev_interpreter=None)  # using evaluation as base
    dual_in = DualNumber(x, x_dot)
    # Here, we short-circuit the tracing: we temporarily override the
    # standard bind by directly calling the JVP interpreter for each op within f.
    # In a full implementation, the bind mechanism would check for an active
    # JVP trace. For simplicity, we rewrite f to operate on dual numbers.
    result = f(dual_in)  
    # The output is a DualNumber; its components represent the value and derivative.
    return result.primal, result.tangent

# ---------------------------------------------------------------------------
# Example usage of the method:

if __name__ == '__main__':
    # Evaluate foo(x) and its derivative at x=2.0.
    primal, derivative = jvp(foo, 2.0, 1.0)
    print(f"foo(2.0) = {primal}")
    print(f"dfoo/dx evaluated at 2.0 = {derivative}")

