// ---------- REDESIGNED UNet Block (training/networks.py) ----------

@persistence.persistent_class
class UNetBlock(torch.nn.Module):
    def __init__(self,
        in_channels, out_channels, emb_channels, up=False, down=False, attention=False,
        num_heads=None, channels_per_head=64, dropout=0, skip_scale=1, eps=1e-5,
        resample_filter=[1,1], resample_proj=False, adaptive_scale=True,
        init=dict(), init_zero=dict(init_weight=0), init_attn=None,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.emb_channels = emb_channels
        # If self-attention is used, set number of heads
        self.num_heads = 0 if not attention else num_heads if num_heads is not None else out_channels // channels_per_head
        self.dropout = dropout
        self.skip_scale = skip_scale
        self.adaptive_scale = adaptive_scale

        // The authors replace the standard normalization with modifications to control
        // the scale of activations. In the original code GroupNorm is used. For the modified
        // version one could substitute it with pixelwise normalization if desired.
        self.norm0 = GroupNorm(num_channels=in_channels, eps=eps)
        self.conv0 = Conv2d(in_channels=in_channels, out_channels=out_channels, kernel=3, up=up, down=down, resample_filter=resample_filter, **init)
        self.affine = Linear(in_features=emb_channels, out_features=out_channels * (2 if adaptive_scale else 1), **init)
        self.norm1 = GroupNorm(num_channels=out_channels, eps=eps)
        self.conv1 = Conv2d(in_channels=out_channels, out_channels=out_channels, kernel=3, **init_zero)

        self.skip = None
        if out_channels != in_channels or up or down:
            // Optionally, a skip connection that resamples the input
            kernel = 1 if resample_proj or out_channels != in_channels else 0
            self.skip = Conv2d(in_channels=in_channels, out_channels=out_channels, kernel=kernel, up=up, down=down, resample_filter=resample_filter, **init)

        if self.num_heads:
            self.norm2 = GroupNorm(num_channels=out_channels, eps=eps)
            self.qkv = Conv2d(in_channels=out_channels, out_channels=out_channels * 3, kernel=1, **(init_attn if init_attn is not None else init))
            self.proj = Conv2d(in_channels=out_channels, out_channels=out_channels, kernel=1, **init_zero)

    def forward(self, x, emb):
        orig = x
        x = self.conv0(silu(self.norm0(x)))

        // Affine modulation using the embedding (e.g., timestep embedding or noise level)
        params = self.affine(emb).unsqueeze(2).unsqueeze(3).to(x.dtype)
        if self.adaptive_scale:
            scale, shift = params.chunk(2, dim=1)
            x = silu(self.norm1(x) * (scale + 1) + shift)
        else:
            x = silu(self.norm1(x + params))

        x = self.conv1(torch.nn.functional.dropout(x, p=self.dropout, training=self.training))
        x = x + (self.skip(orig) if self.skip is not None else orig)
        x = x * self.skip_scale

        if self.num_heads:
            // Self-attention branch computed in FP32 for stability
            q, k, v = self.qkv(self.norm2(x)).reshape(x.shape[0] * self.num_heads, x.shape[1] // self.num_heads, 3, -1).unbind(2)
            w = AttentionOp.apply(q, k)
            a = torch.einsum('nqk,nck->ncq', w, v)
            x = self.proj(a.reshape(*x.shape)) + x
            x = x * self.skip_scale
        return x


// ---------- ADM U-Net Architecture (DhariwalUNet from training/networks.py) ----------

@persistence.persistent_class
class DhariwalUNet(torch.nn.Module):
    """
    This implementation builds upon the ADM U-Net architecture. The network is modified
    to better preserve constant activation and weight scales by employing redesigns in
    the UNet blocks (see above) and normalization adjustments.
    """
    def __init__(self,
        img_resolution,    // Input image resolution
        in_channels,
        out_channels,
        label_dim = 0,
        augment_dim = 0,
        model_channels = 192,
        channel_mult = [1,2,3,4],
        channel_mult_emb = 4,
        num_blocks = 3,
        attn_resolutions = [32,16,8],
        dropout = 0.10,
        label_dropout = 0,
    ):
        super().__init__()
        self.label_dropout = label_dropout
        emb_channels = model_channels * channel_mult_emb
        init = dict(init_mode='kaiming_uniform', init_weight=np.sqrt(1/3), init_bias=np.sqrt(1/3))
        init_zero = dict(init_mode='kaiming_uniform', init_weight=0, init_bias=0)
        block_kwargs = dict(emb_channels=emb_channels, channels_per_head=64, dropout=dropout, init=init, init_zero=init_zero)

        // Mapping network for noise/timestep embedding and class conditioning
        self.map_noise = PositionalEmbedding(num_channels=model_channels)
        self.map_augment = Linear(in_features=augment_dim, out_features=model_channels, bias=False, **init_zero) if augment_dim else None
        self.map_layer0 = Linear(in_features=model_channels, out_features=emb_channels, **init)
        self.map_layer1 = Linear(in_features=emb_channels, out_features=emb_channels, **init)
        self.map_label = Linear(in_features=label_dim, out_features=emb_channels, bias=False, init_mode='kaiming_normal', init_weight=np.sqrt(label_dim)) if label_dim else None

        // Encoder (downsampling path)
        self.enc = torch.nn.ModuleDict()
        cout = in_channels
        for level, mult in enumerate(channel_mult):
            res = img_resolution >> level
            if level == 0:
                cin = cout
                cout = model_channels * mult
                self.enc[f'{res}x{res}_conv'] = Conv2d(in_channels=cin, out_channels=cout, kernel=3, **init)
            else:
                self.enc[f'{res}x{res}_down'] = UNetBlock(in_channels=cout, out_channels=cout, down=True, **block_kwargs)
            for idx in range(num_blocks):
                cin = cout
                cout = model_channels * mult
                self.enc[f'{res}x{res}_block{idx}'] = UNetBlock(in_channels=cin, out_channels=cout, attention=(res in attn_resolutions), **block_kwargs)
        // Skips from encoder used for decoder fusion
        skips = [block.out_channels for name, block in self.enc.items() if 'block' in name or 'conv' in name]

        // Decoder (upsampling path)
        self.dec = torch.nn.ModuleDict()
        for level, mult in reversed(list(enumerate(channel_mult))):
            res = img_resolution >> level
            if level == len(channel_mult) - 1:
                self.dec[f'{res}x{res}_in0'] = UNetBlock(in_channels=cout, out_channels=cout, attention=True, **block_kwargs)
                self.dec[f'{res}x{res}_in1'] = UNetBlock(in_channels=cout, out_channels=cout, **block_kwargs)
            else:
                self.dec[f'{res}x{res}_up'] = UNetBlock(in_channels=cout, out_channels=cout, up=True, **block_kwargs)
            for idx in range(num_blocks + 1):
                cin = cout + skips.pop()
                cout = model_channels * mult
                self.dec[f'{res}x{res}_block{idx}'] = UNetBlock(in_channels=cin, out_channels=cout, attention=(res in attn_resolutions), **block_kwargs)
        self.out_norm = GroupNorm(num_channels=cout, eps=1e-6)
        self.out_conv = Conv2d(in_channels=cout, out_channels=out_channels, kernel=3, **init_zero)

    def forward(self, x, noise_labels, class_labels, augment_labels=None):
        // Mapping stage: combine noise/timestep embeddings with class and augmentation info
        emb = self.map_noise(noise_labels)
        if self.map_augment is not None and augment_labels is not None:
            emb = emb + self.map_augment(augment_labels)
        emb = silu(self.map_layer0(emb))
        emb = silu(self.map_layer1(emb))
        if self.map_label is not None:
            tmp = class_labels
            if self.training and self.label_dropout:
                tmp = tmp * (torch.rand([x.shape[0], 1], device=x.device) >= self.label_dropout).to(tmp.dtype)
            emb = emb + self.map_label(tmp)
        emb = silu(emb)

        // Encoder pass
        skips = []
        for name, block in self.enc.items():
            x = block(x, emb) if isinstance(block, UNetBlock) else block(x)
            skips.append(x)

        // Decoder pass
        for name, block in self.dec.items():
            if x.shape[1] != block.in_channels:
                // Fuse skip connection
                x = torch.cat([x, skips.pop()], dim=1)
            x = block(x, emb)
        x = self.out_conv(silu(self.out_norm(x)))
        return x


// ---------- EMA Update in Training Loop (train.py snippet) ----------

/* In the training loop, to incorporate the power-function based EMA profile and
   enable post-hoc EMA reconstruction, the EMA update is computed as follows:
*/

// Assume the following variables have been defined:
//   - net: the current network
//   - ema: the exponential moving average copy of net
//   - batch_size: total batch size
//   - ema_halflife_kimg: EMA half-life in thousands of images
//   - ema_rampup_ratio: Optional ramp-up ratio for EMA (to gradually use EMA early in training)
//   - cur_nimg: current number of images processed

ema_halflife_nimg = ema_halflife_kimg * 1000
if ema_rampup_ratio is not None:
    ema_halflife_nimg = min(ema_halflife_nimg, cur_nimg * ema_rampup_ratio)

// Compute the EMA decay. Here the decay beta is computed using a power function:
ema_beta = 0.5 ** (batch_size / max(ema_halflife_nimg, 1e-8))

// Update exponential moving average of network parameters
for p_ema, p_net in zip(ema.parameters(), net.parameters()):
    p_ema.copy_(p_net.detach().lerp(p_ema, ema_beta))

/* Post-hoc EMA reconstruction: after training, one can fine-tune or re-evaluate
   different EMA averaging settings (by varying ema_halflife or the effective beta)
   without restarting training. This mechanism is integrated to allow exploration
   of configurations (denoted as CONFIG A to CONFIG G) corresponding to various
   ablations of design decisions (e.g. weight normalization adjustments, activation
   scaling, and EMA profile modifications).
*/

